from inspect import Parameter, signature

import torch
import torch.nn as nn

from amct_pytorch.algorithms.registry_factory import ALGO_REGISTRY
from amct_pytorch.quantization.dtypes import DTYPE_REGISTRY


def get_algo_names_by_target(args, target):
    selected = []
    for algo_name in args.algos:
        algo_item = ALGO_REGISTRY.get_item(algo_name)
        targets = tuple(algo_item.metadata.get("targets", ()))
        if not targets:
            raise ValueError(
                f"Algorithm '{algo_name}' is missing registry metadata 'targets'."
            )
        if target in targets:
            selected.append(algo_name)
    return selected


def build_algorithms_by_target(args, target, *ctor_args):
    algorithms = nn.ModuleDict()
    algo_names = get_algo_names_by_target(args, target)
    for algo_name in algo_names:
        algo_item = ALGO_REGISTRY.get_item(algo_name)
        targets = tuple(algo_item.metadata.get("targets", ()))
        if not targets:
            raise ValueError(
                f"Algorithm '{algo_name}' is missing registry metadata 'targets'."
            )
        if target not in targets:
            raise ValueError(
                f"Algorithm '{algo_name}' cannot be used for target '{target}'. "
                f"Declared targets: {targets}"
            )
        algorithms[algo_name] = _build_algorithm(algo_item.target, args, *ctor_args)
    if target == "structure":
        if len(algorithms) == 0:
            return None
        if len(algorithms) > 1:
            raise ValueError(
                f"Only one '{target}' algorithm is supported here, got: {list(algorithms.keys())}"
            )
        return next(iter(algorithms.values()))
    else:
        return algorithms


def _build_algorithm(algo_cls, args, *ctor_args):
    init_params = list(signature(algo_cls.__init__).parameters.values())
    positional_params = [
        param
        for param in init_params[1:]
        if param.kind in (Parameter.POSITIONAL_ONLY, Parameter.POSITIONAL_OR_KEYWORD)
    ]
    has_varargs = any(param.kind == Parameter.VAR_POSITIONAL for param in init_params)
    if has_varargs or len(positional_params) > 1:
        return algo_cls(args, *ctor_args)
    return algo_cls(args)


class ActivationQuantizer(torch.nn.Module):
    def __init__(self, args, bits):
        super(ActivationQuantizer, self).__init__()
        self.args = args
        self.bits = bits
        self.algorithms = nn.ModuleDict()
        self._init_algo()
        self.quant_obj = DTYPE_REGISTRY.get(args.quant_dtype)(
            bits=self.bits, is_act=True
        )
        self.is_observe = False

    def deploy(self):
        pass

    def fake_quant(self, x):
        if self.is_observe:
            return x
        return self.quant_obj(x)

    def forward(self, x):
        for algo in self.algorithms.values():
            x = algo.calib_forward(x) if self.is_observe else algo(x)
        return self.fake_quant(x)

    def load_deploy(self, scale, zero):
        pass

    def trainable_params(self):
        params = []
        for algo in self.algorithms.values():
            if hasattr(algo, "trainable_params"):
                params.extend(algo.trainable_params())
        return params

    def _init_algo(self):
        self.algorithms = build_algorithms_by_target(self.args, "activation")


class WeightQuantizer(torch.nn.Module):
    def __init__(self, args, w_bits=None):
        super(WeightQuantizer, self).__init__()
        self.args = args
        self.bits = w_bits if w_bits is not None else args.w_bits
        self.algorithms = nn.ModuleDict()
        self._init_algo()
        self.quant_obj = DTYPE_REGISTRY.get(args.quant_dtype)(bits=self.bits)
        self.is_observe = False

    def algo_forward(self, x):
        quantize_algo = None
        for algo in self.algorithms.values():
            if self.is_observe:
                x = algo.calib_forward(x)
                continue
            quantize_fn = getattr(algo, "quantize", None)
            if callable(quantize_fn):
                if quantize_algo is not None:
                    raise ValueError(
                        "Only one weight algorithm with a custom quantize() hook is supported."
                    )
                quantize_algo = algo
                continue
            x = algo(x)
        return x, quantize_algo

    def export_deploy(self, x):
        x, quantize_algo = self.algo_forward(x)
        if quantize_algo is not None:
            export_fn = getattr(quantize_algo, "export_deploy", None)
            if not callable(export_fn):
                raise NotImplementedError(
                    "export_deploy() does not support custom weight quantize() hooks yet."
                )
            return export_fn(x, self.quant_obj)
        export_fn = getattr(self.quant_obj, "export_deploy", None)
        if not callable(export_fn):
            raise NotImplementedError(
                f"Quant dtype '{self.args.quant_dtype}' does not implement export_deploy()."
            )
        return export_fn(x)

    def fake_quant(self, x):
        if self.is_observe:
            return x
        return self.quant_obj(x)

    def forward(self, x):
        x, quantize_algo = self.algo_forward(x)
        if quantize_algo is not None:
            return quantize_algo.quantize(x, self.quant_obj)
        return self.fake_quant(x)

    def observe_input(self, x, weight=None):
        for algo in self.algorithms.values():
            observe_input = getattr(algo, "observe_input", None)
            if callable(observe_input):
                observe_input(x, weight)

    def trainable_params(self):
        params = []
        for algo in self.algorithms.values():
            if hasattr(algo, "trainable_params"):
                params.extend(algo.trainable_params())
        return params

    def _init_algo(self):
        self.algorithms = build_algorithms_by_target(self.args, "weight", self.bits)

        quant_args, mlp_module.down_proj, w_bits=down.w, name="down_proj"
    )
    self.input_quant = ActivationQuantizer(quant_args, gate.a)
    self.hidden_quant = ActivationQuantizer(quant_args, down.a)

def forward(self, input_states):
    if self.input_transform is not None:
        input_states = self.input_transform(input_states)
    x_q = self.input_quant(input_states)
    up = self.up_proj(x_q, structure_transform=self.input_transform)
    gate = self.gate_proj(x_q, structure_transform=self.input_transform)

    hidden = self.act_fn(gate) * up
    if self.hidden_transform is not None:
        hidden = self.hidden_transform(hidden)

    hidden_q = self.hidden_quant(hidden)
    down_states = self.down_proj(
        hidden_q, structure_transform=self.hidden_transform
    )
    return down_states

def export_ptq_params(self):
    params = PtqParamHandler.export_module(self)
    if params:
        return params
    return PtqParamHandler.export_trainable_module(self)

def load_ptq_params(self, params):
    if (
        isinstance(params, dict)
        and params
        and all(isinstance(v, dict) for v in params.values())
    ):
        PtqParamHandler.load_module(self, params)
        return
    PtqParamHandler.load_trainable_module(self, params)

def _init_structure_transforms(self):
    ctx = AlgoBuildContext(matrix_size=128, dim_size=self.hidden_size)
    self.input_transform = build_algorithms_by_target(
        self.quant_args, "structure", ctx
    )
    ctx = AlgoBuildContext(matrix_size=128, dim_size=self.intermediate_size)
    self.hidden_transform = build_algorithms_by_target(
        self.quant_args, "structure", ctx
    )
